uniform float iTime;
uniform vec2 iResolution;
uniform vec4 iMouse;
uniform sampler2D iChannel0;

// Audio Reactivity
uniform float u_bass;
uniform float u_mid;
uniform float u_treble;
uniform float u_vol;

// Mandatory Parameters
uniform float u_speed;
uniform float u_complexity;
uniform float u_glow_intensity;
uniform float u_color_shift;
uniform float u_alpha_fade;
uniform float u_brightness_fix;
uniform float u_zoom;
uniform float u_sharpness;
uniform float u_saturation;
uniform float u_contrast;

// Depth Magic Parameters
uniform float u_parallax;
uniform float u_fog_density;

// Biological Parameters
uniform float u_vein_thickness;
uniform float u_3d_warp;
uniform float u_synapse_freq;

out vec4 fragColor;

// 2D Rotation Matrix
mat2 rot(float a) {
    float s = sin(a);
    float c = cos(a);
    return mat2(c, -s, s, c);
}

// Color processing helpers
vec3 saturate(vec3 rgb, float adjustment) {
    const vec3 W = vec3(0.2125, 0.7154, 0.0721);
    vec3 intensity = vec3(dot(rgb, W));
    return mix(intensity, rgb, adjustment);
}

vec3 contrast(vec3 rgb, float adjustment) {
    return (rgb - 0.5) * adjustment + 0.5;
}

// Hash for noise
vec2 hash22(vec2 p) {
    vec3 p3 = fract(vec3(p.xyx) * vec3(.1031, .1030, .0973));
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.xx + p3.yz) * p3.zy);
}

float hash12(vec2 p) {
	vec3 p3  = fract(vec3(p.xyx) * .1031);
    p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.x + p3.y) * p3.z);
}

// Neural connection generator using Voronoi-based segments to remove "checkered" look
float neuralPath(vec2 p, float depth, float time) {
    p *= (1.0 + depth * 0.1) * u_synapse_freq; 

    // Distort space to look biological/organic
    p += sin(p.yx * 1.2 + time * 0.5) * 0.4 * u_3d_warp;

    vec2 i = floor(p);
    vec2 f = fract(p);

    float min_dist = 1.0;
    float edge_dist = 1.0;

    // Find nearest neighbor for core neuron body
    vec2 res = vec2(8.0);
    for(int y=-1; y<=1; y++) {
        for(int x=-1; x<=1; x++) {
            vec2 g = vec2(float(x),float(y));
            vec2 o = hash22(i + g);
            o = 0.5 + 0.5 * sin(time + 6.2831 * o);
            vec2 r = g + o - f;
            float d = dot(r,r);
            if(d < res.x) {
                res.y = res.x;
                res.x = d;
            } else if(d < res.y) {
                res.y = d;
            }
        }
    }

    // Create organic dendrites by finding the distance to the "ridge" between voronoi cells
    // This looks much more like neural connectivity than a grid.
    float distToEdge = res.y - res.x;
    float line = smoothstep(u_vein_thickness * 2.0, u_vein_thickness, distToEdge);

    // Add pulsing signals moving along the lines
    float signal = smoothstep(0.9, 1.0, sin(distToEdge * 20.0 - time * 4.0));

    return line + signal * 0.3;
}

// Organic wave with integrated depth-based parallax
float organicWave(vec2 uv, float depth, float offset) {
    float t = iTime * u_speed * 0.3 + offset;
    vec2 p = uv * (1.0 + depth * 0.1);

    // Shift p based on depth to create "Depth Magic" parallax
    vec2 mouseEffect = (iMouse.xy / iResolution.xy - 0.5) * depth * u_parallax;
    p += mouseEffect;

    // Add cellular distortion
    p.x += sin(p.y * 1.5 + t) * 0.2;
    p.y += cos(p.x * 1.5 + t * 0.7) * 0.2;

    // Blend a base organic flow with the neural connectivity paths
    float neural = neuralPath(p * 0.8, depth, t);

    return neural;
}

void main() {
    vec2 uv = (gl_FragCoord.xy - 0.5 * iResolution.xy) / iResolution.y;
    uv *= u_zoom;

    float t = iTime * u_speed * 0.2;

    // Mouse interaction for the camera "lean"
    vec2 mouseOffset = (iMouse.xy / iResolution.xy - 0.5) * 0.2 * u_parallax;
    uv -= mouseOffset;

    // Biological Palette (Fleshy/Neural)
    vec3 colorA = vec3(0.04, 0.01, 0.02); // Deep tissue/blood
    vec3 colorB = vec3(0.7, 0.15, 0.25);   // Capillary Red
    vec3 colorC = vec3(0.3, 0.5, 1.0);    // Neural Electrical Blue
    vec3 colorD = vec3(1.0, 0.9, 0.7);    // Synaptic Flash

    // Apply color shift
    colorB = mix(colorB, vec3(0.1, 0.5, 0.4), u_color_shift); 
    colorC = mix(colorC, vec3(0.5, 0.1, 0.8), u_color_shift); 

    // Initial background gradient
    vec3 finalColor = mix(colorA, colorB * 0.15, (uv.y / u_zoom) + 0.5);

    // Layered Depth Rendering (3D Stack)
    float layers = clamp(u_complexity, 1.0, 10.0);
    for(float i = 0.0; i < 10.0; i++) {
        if(i >= layers) break;

        float z = i + 1.0;
        float flow = organicWave(uv, z, i * 1.7);

        // Use flow as a mask for the neural strands
        float mask = smoothstep(0.1, 0.8, flow);

        // Pulse color based on audio/time
        float pulse = sin(t * 2.0 - i * 0.4 + u_bass) * 0.5 + 0.5;
        vec3 waveColor = mix(colorB, colorC, pulse);

        // Depth-based "Fog"
        float depthFog = exp(-i * (u_fog_density + 0.15));
        waveColor = mix(colorA, waveColor, depthFog);

        // Audio reactivity: Synapses fire on bass
        float fire = step(0.95, hash12(vec2(i, floor(t * 8.0))));
        waveColor += colorD * (u_bass * 0.8 * depthFog * fire); 

        float alphaFactor = mix(0.1, 0.4, u_sharpness) / (z * 0.7);
        finalColor += waveColor * flow * alphaFactor;
    }

    // Synaptic Glow (The 3D "Center")
    float dist = length(uv + mouseOffset * 2.5);
    float synapsePulse = (1.0 + u_mid * 0.5 + u_treble * 0.3);
    float glowPower = mix(4.0, 10.0, u_sharpness);
    float glow = exp(-dist * (glowPower / (max(u_glow_intensity, 0.1) * synapsePulse * u_zoom)));
    finalColor += colorC * glow * 0.3;
    finalColor += colorD * pow(glow, 3.0) * 0.7; // Hot white center

    // Floating Biological Particles (Leukocytes/Cells)
    for(float i = 0.0; i < 8.0; i++) {
        float p_depth = fract(i * 0.31 + t * 0.1); 
        float p_t = t + i * 45.67;

        vec2 p_pos = vec2(sin(p_t * 0.3), cos(p_t * 0.2)) * u_zoom * 1.5;
        p_pos += mouseOffset * (3.0 / (p_depth + 0.1)) * u_parallax;

        float p_size = (0.02 + 0.05 * (1.0 - p_depth)) * u_zoom;
        float p_dist = length(uv - p_pos);

        float cell = smoothstep(p_size, p_size * 0.2, p_dist);
        finalColor += mix(colorB, colorD, p_depth) * cell * (1.0 - p_depth) * 0.3;
    }

    // --- Post Processing ---
    finalColor = saturate(finalColor, u_saturation);
    finalColor = contrast(finalColor, u_contrast);
    finalColor *= u_brightness_fix;

    // Organic Vignette
    vec2 screenUV = (gl_FragCoord.xy / iResolution.xy) - 0.5;
    float vignette = 1.0 - dot(screenUV, screenUV) * 1.8;
    finalColor *= clamp(vignette, 0.0, 1.0);

    // Film Grain / Biological Micro-noise
    finalColor += (hash12(uv + iTime) - 0.5) * 0.04;

    fragColor = vec4(finalColor, u_alpha_fade);
}
